const driftY = K.t * 0.030 * spd + S.o2;
const bph = K.t * 0.066 * spd + K.section * 0.7;          // bloom envelope phase
const morphX = Math.sin(K.t*0.018*spd + K.section*1.7) * 3.5;  // slow blot reshape -> new blots
const morphY = Math.cos(K.t*0.015*spd + K.section*1.3) * 3.5;
const hb = (P.hue + S.hoff*30 + K.section*10) % 360;

const spread = P.spread, dens = P.density, energy = P.energy, bleed = P.bleed;
const fscale = 2.4 / (0.45 + P.scale * 1.0);
const edgeW = 0.10 + bleed * 0.55;                        // wet-edge feather width
const noiseAmp = 1.5 * (0.35 + dens);                     // tendril amplitude
